/**
 * D05 Runtime Stays: short-term rental listings in "Riverton", a fictional city, generated by Runtime in the shape of
 * public listings exports (Inside Airbnb style): listings, hosts, a 90-day availability calendar and reviews.
 *
 * Generated instead of acquired: Inside Airbnb's files carry hosts' names and photos and per-city terms, which this
 * course doesn't redistribute. Every host, listing and review here is invented. The shape and messiness are real:
 * prices as "$1,250.00" text, amenities as a JSON list inside one CSV cell, bathrooms as text ("1.5 shared baths"),
 * percentages as text, "t"/"f" booleans, licence numbers in mixed formats, listings without reviews.
 */
import { createRng, hash32, ts, ms, DAY, round2 } from '../../lib/rng.mjs';

const SEED = 20260505;
const col = (name, type, description, nullable = false) => ({ name, type, description, nullable });
const START = ms('2025-06-01');
const NEIGHBOURHOODS = [
  ['Old Town', 'Central', 45.512, -122.676, 1.6, 18], ['Riverside', 'Central', 45.522, -122.668, 1.5, 14], ['Pearl Quarter', 'Central', 45.528, -122.684, 1.45, 12],
  ['Northgate', 'North', 45.556, -122.680, 1.0, 9], ['Mill Park', 'North', 45.571, -122.701, 0.9, 6], ['Harbor Flats', 'North', 45.585, -122.735, 0.8, 4],
  ['Eastmoreland', 'East', 45.477, -122.636, 1.05, 8], ['Hawthorne', 'East', 45.512, -122.625, 1.15, 12], ['Laurel Heights', 'East', 45.531, -122.612, 1.0, 7],
  ['Foster', 'East', 45.493, -122.575, 0.75, 5], ['Hillside', 'West', 45.515, -122.712, 1.35, 6], ['Cedar Hills', 'West', 45.498, -122.765, 0.95, 4],
  ['South Waterfront', 'South', 45.497, -122.672, 1.25, 7], ['Sellwood', 'South', 45.465, -122.652, 1.0, 6], ['Airport Way', 'North', 45.578, -122.583, 0.7, 3],
];
const ROOM = [['Entire home/apt', 66], ['Private room', 29], ['Shared room', 2], ['Hotel room', 3]];
const PLACES = ['condo', 'bungalow', 'loft', 'studio', 'craftsman', 'cottage', 'townhouse', 'suite', 'apartment', 'tiny house', 'garden unit', 'attic room'];
const ADJ = ['Sunny', 'Cozy', 'Modern', 'Charming', 'Quiet', 'Bright', 'Spacious', 'Stylish', 'Walkable', 'Light-filled', 'Historic', 'Minimalist', 'Lush', 'Hip'];
const PERKS = ['near cafés', 'with garden', 'free parking', 'king bed', 'fast WiFi', 'hot tub', 'river views', 'by the park', 'EV charger', 'pet friendly', 'rooftop deck', 'walk to downtown'];
const AMENITIES = ['Wifi', 'Kitchen', 'Smoke alarm', 'Essentials', 'Hair dryer', 'Hangers', 'Heating', 'Air conditioning', 'Washer', 'Dryer', 'Dedicated workspace', 'Free parking on premises', 'Free street parking', 'Coffee maker', 'Microwave', 'Dishwasher', 'Hot tub', 'Pets allowed', 'Self check-in', 'Lockbox', 'TV', 'Iron', 'Carbon monoxide alarm', 'First aid kit', 'Fire extinguisher', 'Patio or balcony', 'EV charger', 'Long term stays allowed', 'Crib', 'Bathtub', 'Backyard', 'BBQ grill', 'Gym', 'Elevator'];
const FIRST = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Jamie', 'Avery', 'Quinn', 'Drew', 'Reese', 'Elena', 'Marcus', 'Priya', 'Hiro', 'Fatima', 'Lucas', 'Sofia', 'Noah', 'Mei', 'Omar', 'Grace', 'Ivan', 'Lena', 'Diego'];
const REVIEWERS = ['Anna', 'Ben', 'Carla', 'Dev', 'Eli', 'Fiona', 'Gabe', 'Hana', 'Ian', 'Jules', 'Kai', 'Lia', 'Mo', 'Nadia', 'Owen', 'Pia', 'Raj', 'Sara', 'Tom', 'Uma', 'Vik', 'Wren', 'Yusuf', 'Zoe', 'Marie', 'Luis', 'Chen', 'Aiko'];
const OPEN = ['Great place to stay!', 'Lovely spot.', 'Exactly as described.', 'We had a wonderful time.', 'Perfect for a weekend away.', 'Very clean and comfortable.', 'Host was super responsive.', 'Good value.', 'Nice, but a bit noisy at night.', 'Smaller than it looked in photos.', 'Would definitely stay again!', 'Check-in was easy.'];
const MORE = ['The neighbourhood is walkable with great coffee nearby.', 'Bed was very comfortable.', 'Kitchen had everything we needed.', 'Parking was a little tricky.', 'The WiFi was slow during our stay.', 'Highly recommend!', 'The place could use a deeper clean.', 'Thanks for the local tips!', 'Quiet street, easy bus to downtown.', 'Shower pressure was low.', 'Loved the garden.', ''];
const FOREIGN = ['Très bon séjour, logement propre et bien situé.', 'Muy buena ubicación, el anfitrión fue muy amable.', 'Sehr schöne Wohnung, gerne wieder!', 'とても清潔で快適でした。'];

const money = x => `$${x.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

function generate() {
  const rng = createRng(SEED);
  const hRng = rng.fork('hosts');
  const hosts = [];
  const nHosts = 1900;
  for (let id = 1; id <= nHosts; id++) {
    const since = ms('2010-01-01') + Math.floor(hRng.next() ** 0.7 * (ms('2025-05-01') - ms('2010-01-01')));
    const pro = hRng.chance(0.06);
    hosts.push({
      host_id: 100000 + id * 37, host_name: pro ? `${hRng.pick(['Riverton', 'Urban', 'Northwest', 'Cascade', 'Rose'])} ${hRng.pick(['Stays', 'Homes', 'Rentals', 'Hospitality'])}` : hRng.pick(FIRST),
      host_since: ts(since).slice(0, 10), host_is_superhost: hRng.chance(pro ? 0.5 : 0.3) ? 't' : 'f',
      host_response_rate: hRng.chance(0.15) ? 'N/A' : `${Math.min(100, Math.round(100 - hRng.exponential(6)))}%`,
      host_response_time: hRng.weighted([['within an hour', 55], ['within a few hours', 22], ['within a day', 13], ['a few days or more', 3], [null, 7]]),
      host_identity_verified: hRng.chance(0.88) ? 't' : 'f', _listings: pro ? hRng.int(4, 30) : hRng.chance(0.15) ? 2 : 1,
    });
  }
  const lRng = rng.fork('listings');
  const listings = [];
  let lid = 0;
  for (const h of hosts) {
    for (let k = 0; k < h._listings; k++) {
      lid++;
      const [hood, area, lat, lon, priceF] = lRng.weighted(NEIGHBOURHOODS.map(n => [n, n[5]]));
      const room = lRng.weighted(ROOM);
      const entire = room === 'Entire home/apt';
      const bedrooms = room === 'Shared room' ? null : entire ? lRng.weighted([[1, 45], [2, 30], [3, 15], [4, 7], [5, 3]]) : 1;
      const accommodates = Math.max(1, (bedrooms ?? 1) * lRng.int(1, 2) + (entire ? lRng.int(0, 2) : 0));
      const baths = entire ? Math.max(1, Math.round(((bedrooms ?? 1) * lRng.float(0.5, 1.1)) * 2) / 2) : 1;
      const bathText = room === 'Shared room' || (!entire && lRng.chance(0.55)) ? `${baths} shared bath${baths === 1 ? '' : 's'}` : baths === 0.5 ? 'Half-bath' : `${baths} ${room === 'Private room' ? 'private ' : ''}bath${baths === 1 ? '' : 's'}`;
      const base = (entire ? 95 + 55 * (bedrooms - 1) : room === 'Hotel room' ? 140 : room === 'Shared room' ? 38 : 62) * priceF * lRng.lognormal(1, 0.28);
      const price = Math.round(base);
      const amen = lRng.shuffle(AMENITIES).slice(0, lRng.int(8, 30));
      const reviewsPerMonth = lRng.chance(0.14) ? 0 : Math.max(0.05, lRng.lognormal(1.2, 0.9));
      const minN = lRng.weighted([[1, 30], [2, 30], [3, 15], [30, 20], [7, 5]]);
      listings.push({
        listing_id: 4000000 + lid * 101, host_id: h.host_id,
        name: `${lRng.pick(ADJ)} ${lRng.pick(PLACES)} ${lRng.pick(PERKS)}`.replace(/^\w/, c => c.toUpperCase()),
        neighbourhood: hood, neighbourhood_group: area,
        latitude: Math.round((lat + lRng.normal(0, 0.009)) * 1e5) / 1e5, longitude: Math.round((lon + lRng.normal(0, 0.011)) * 1e5) / 1e5,
        room_type: room, accommodates, bathrooms_text: bathText, bedrooms, beds: bedrooms === null ? 1 : bedrooms + (lRng.chance(0.3) ? 1 : 0),
        amenities: JSON.stringify(amen), price: money(price), minimum_nights: minN, maximum_nights: lRng.weighted([[1125, 60], [365, 15], [30, 15], [90, 10]]),
        instant_bookable: lRng.chance(0.35) ? 't' : 'f',
        license: minN >= 30 ? 'Exempt' : lRng.weighted([[`STR-${lRng.int(10000, 99999)}`, 50], [`${lRng.int(2019, 2025)}-${lRng.int(100000, 999999)}`, 25], ['pending', 8], [null, 17]]),
        _price: price, _rpm: reviewsPerMonth, _since: Math.max(ms(h.host_since), ms('2015-01-01')) + lRng.int(0, 400) * DAY, _q: lRng.normal(0, 0.25),
      });
    }
  }
  // Calendar: 90 days from 2025-06-01; weekend and summer prices; booked nights are unavailable.
  const cRng = rng.fork('calendar');
  const calendar = [];
  for (const l of listings) {
    const busy = Math.min(0.92, 0.25 + l._rpm * 0.12);
    for (let d = 0; d < 90; d++) {
      const t = START + d * DAY;
      const dow = new Date(t).getUTCDay();
      const factor = (dow === 5 || dow === 6 ? 1.18 : 1) * (d < 75 ? 1.08 : 1);
      calendar.push({ listing_id: l.listing_id, date: ts(t).slice(0, 10), available: cRng.chance(busy) ? 'f' : 't', price: money(Math.round(l._price * factor)), minimum_nights: l.minimum_nights });
    }
  }
  // Reviews: Poisson count from reviews-per-month since the listing started.
  const rRng = rng.fork('reviews');
  const reviews = [];
  let rid = 0;
  for (const l of listings) {
    const months = Math.max(1, (START - l._since) / (30 * DAY));
    const n = rRng.poisson(Math.min(200, l._rpm * months * 0.22));
    for (let k = 0; k < n; k++) {
      rid++;
      const at = l._since + Math.floor(rRng.next() ** 0.7 * (START - l._since));
      const text = rRng.chance(0.04) ? rRng.pick(FOREIGN) : rRng.chance(0.03) ? '' : `${rRng.pick(OPEN)} ${rRng.pick(MORE)}`.trim();
      reviews.push({ review_id: 90000000 + rid * 13, listing_id: l.listing_id, date: ts(at).slice(0, 10), reviewer_name: rRng.pick(REVIEWERS), comments: text || null });
    }
  }
  reviews.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.review_id - b.review_id));
  // Listing review summaries follow from the reviews.
  const byListing = new Map();
  for (const r of reviews) (byListing.get(r.listing_id) ?? byListing.set(r.listing_id, []).get(r.listing_id)).push(r);
  for (const l of listings) {
    const rs = byListing.get(l.listing_id) ?? [];
    l.number_of_reviews = rs.length;
    l.last_review = rs.at(-1)?.date ?? null;
    l.review_scores_rating = rs.length ? Math.min(5, round2(4.72 + l._q - 0.15 * rRng.next())) : null;
  }
  const strip = o => Object.fromEntries(Object.entries(o).filter(([k]) => !k.startsWith('_')));
  return { hosts: hosts.map(strip), listings: listings.map(strip), calendar, reviews };
}

const EDITIONS = { preview: { listings: 8, days: 3 }, starter: { listings: 120, days: 30 }, standard: { listings: 700, days: 90 }, full: { listings: Infinity, days: 90 } };

function cutEdition(full, edition) {
  const e = EDITIONS[edition];
  const listings = e.listings === Infinity ? full.listings : full.listings.slice().sort((a, b) => hash32(`${edition}|${a.listing_id}`) - hash32(`${edition}|${b.listing_id}`)).slice(0, e.listings).sort((a, b) => a.listing_id - b.listing_id);
  const ids = new Set(listings.map(l => l.listing_id));
  const hostIds = new Set(listings.map(l => l.host_id));
  const last = ts(START + (e.days - 1) * DAY).slice(0, 10);
  let reviews = full.reviews.filter(r => ids.has(r.listing_id));
  if (edition === 'preview') reviews = reviews.slice(-20);
  return { hosts: full.hosts.filter(h => hostIds.has(h.host_id)), listings, calendar: full.calendar.filter(c => ids.has(c.listing_id) && c.date <= last), reviews };
}

function realIssues({ listings, reviews }) {
  return [
    { id: 'price_text', description: 'Prices stored as text with "$" and thousands separators', count: listings.length },
    { id: 'amenities_json', description: 'Amenities stored as a JSON list inside one CSV cell', count: listings.length },
    { id: 'bathrooms_text', description: 'Bathrooms as text ("1.5 shared baths", "Half-bath") instead of a number', count: listings.length },
    { id: 'no_reviews', description: 'Listings with no reviews (no score, no last review date)', count: listings.filter(l => l.number_of_reviews === 0).length },
    { id: 'licence_formats', description: 'Licence values in mixed formats, "pending", "Exempt" or empty', count: listings.filter(l => !l.license || !l.license.startsWith('STR-')).length },
    { id: 'empty_or_foreign_reviews', description: 'Reviews that are empty or not in English', count: reviews.filter(r => !r.comments || /[^\x00-\x7F]/.test(r.comments)).length },
  ];
}

const dataset = {
  id: 'D05',
  title: 'Runtime Stays',
  version: 1,
  seed: SEED,
  description:
    'Fictional short-term rentals in Riverton, an invented city: listings, hosts, a 90-day availability calendar and ' +
    'guest reviews, generated by Runtime in the shape of public listings exports, messy text columns included.',
  licence: { name: 'Runtime-owned synthetic data', status: 'ours' },
  generator: 'datasets/python/D05/dataset.mjs',
  window: ['2010-01-01', '2025-08-29'],
  tables: {
    hosts: {
      description: 'One host account. A few professional hosts run many listings.',
      primaryKey: ['host_id'],
      columns: [
        col('host_id', 'integer', 'Host ID'), col('host_name', 'text', 'Invented first name or company'), col('host_since', 'date', 'Joined'),
        col('host_is_superhost', 'text', '"t" (yes) or "f" (no)'), col('host_response_rate', 'text', 'Percent as text ("96%") or "N/A"'),
        col('host_response_time', 'text', 'Typical response time', true), col('host_identity_verified', 'text', '"t" (yes) or "f" (no)'),
      ],
    },
    listings: {
      description: 'One listing.',
      primaryKey: ['listing_id'],
      foreignKeys: [{ column: 'host_id', references: 'hosts.host_id' }],
      columns: [
        col('listing_id', 'integer', 'Listing ID'), col('host_id', 'integer', 'Host'), col('name', 'text', 'Listing title'),
        col('neighbourhood', 'text', 'Neighbourhood'), col('neighbourhood_group', 'text', 'Area of the city'), col('latitude', 'decimal', 'Latitude (approximate)'), col('longitude', 'decimal', 'Longitude (approximate)'),
        col('room_type', 'text', 'Entire home/apt, Private room, Shared room or Hotel room'), col('accommodates', 'integer', 'Guests'),
        col('bathrooms_text', 'text', 'Bathrooms as text'), col('bedrooms', 'integer', 'Bedrooms; empty for shared rooms', true), col('beds', 'integer', 'Beds'),
        col('amenities', 'text', 'JSON list of amenities'), col('price', 'text', 'Nightly price as text, "$1,250.00"'),
        col('minimum_nights', 'integer', 'Minimum stay'), col('maximum_nights', 'integer', 'Maximum stay'), col('instant_bookable', 'text', '"t" (yes) or "f" (no)'),
        col('license', 'text', 'City licence number, "pending", "Exempt" or empty', true), col('number_of_reviews', 'integer', 'Reviews so far'),
        col('last_review', 'date', 'Date of the latest review', true), col('review_scores_rating', 'decimal', 'Average rating out of 5', true),
      ],
    },
    calendar: {
      description: 'One night of one listing: available or booked, and the asking price. 90 nights from 1 June 2025.',
      primaryKey: ['listing_id', 'date'],
      foreignKeys: [{ column: 'listing_id', references: 'listings.listing_id' }],
      columns: [col('listing_id', 'integer', 'Listing'), col('date', 'date', 'Night'), col('available', 'text', '"t" free, "f" booked or blocked'), col('price', 'text', 'Price as text'), col('minimum_nights', 'integer', 'Minimum stay that night')],
    },
    reviews: {
      description: 'One guest review.',
      primaryKey: ['review_id'],
      foreignKeys: [{ column: 'listing_id', references: 'listings.listing_id' }],
      columns: [col('review_id', 'integer', 'Review ID'), col('listing_id', 'integer', 'Listing'), col('date', 'date', 'Date'), col('reviewer_name', 'text', 'Invented first name'), col('comments', 'text', 'Review text; sometimes empty or not in English', true)],
    },
  },
  editions: Object.fromEntries(Object.keys(EDITIONS).map(k => [k, k])),
  parquet: { tables: ['calendar'] },
  stress: false,
  generate,
  cutEdition,
  realIssues,
};

export default dataset;
